package paging

// PageCount is how many pages of size items it takes to hold total items.
func PageCount(total, size int) int {
	if size <= 0 {
		return 0
	}
	return (total + size - 1) / size
}

// Page returns the items of page n (1-based), size items per page.
func Page(items []string, n, size int) []string {
	start := n * size
	end := start + size
	if end > len(items) {
		end = len(items)
	}
	return items[start:end]
}

